#!/usr/bin/env python3
"""Audit whether killing Gamma alone defines the claimed rank-26 chain quotient."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]/'results';x=json.loads((R/'cosmology_rank27_cone_differential_dpc.json').read_text())
t=x['strongest_falsification_attempt'];assert t['generator']=='Gamma';assert t['first_differential']==['Xi_rel','-sigma123'];assert t['second_differential']==0
boundary=t['first_differential'];assert boundary!=[0,0]
out={'schema':'marici.benincasa.cosmology-gamma-quotient-chain-descent-dpc.v1','problem':'Can physical descent recover the rank-26 complex by killing precisely the Gamma direction?','bold_conjecture':'The subgroup generated by Gamma is a subcomplex, so quotienting E_Gamma by Gamma yields the original rank-26 chain complex R.','named_rivals':['D(Gamma) is the nonzero class (Xi_rel,-sigma123), so Gamma alone is not a subcomplex','a chain quotient killing Gamma must also kill its boundary','the result is a further quotient of R rather than R itself'],'risky_consequences':['D(Gamma) must lie in the subgroup generated by Gamma','the induced differential on the quotient must be well-defined without imposing a relation in R'],'strongest_falsification_attempt':{'D_Gamma':boundary,'D2_Gamma':0,'Gamma_subgroup_closed_under_D':False,'forced_additional_relation_in_R':'Xi_rel-sigma123 pair equals zero'},'disposition':{'status':'falsified as a chain-complex descent','residual':'killing Gamma alone is incompatible with D(Gamma) nonzero; the differential descends only after also quotienting R by the boundary class','surviving_scope':'E_Gamma/<Gamma> is isomorphic to R only as an abelian group after choosing the sourced splitting, not as the stated chain complex','reopening_test':'supply a physical record map whose kernel is a subcomplex and compute whether its intersection with R is zero; the present Gamma-only kernel cannot satisfy this'},'passed':True};(R/'cosmology_gamma_quotient_chain_descent_dpc.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
